describe('turn usage', () => {
  // specs/hal-engine-config-hooks/spec.md#10
  it('adds usage from provider calls across a tool round', async () => {
    const rounds: MessageChunk[][] = [
      [
        {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}},
        {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}},
      ],
      [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 11, totalTokens: 18}}],
    ];
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage() {
        yield* rounds[round++] ?? [];
      },
      async generateStructured<T>() {
        return {} as T;
      },
    };
    const tools = new ToolRegistry();
    tools.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
    let reported: UsageMetadata | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), tools, {
      hooks: {
        afterModelResponse: async (_session, _text, usage) => {
          reported = usage;
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's',
      userId: 'u',
      entries: [{role: 'user', content: 'Hi', timestamp: '2026-01-01T00:00:00.000Z'}],
    };

    await orchestrator.processMessage(session);

    expect(reported).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
